<script setup>
import { computed,onMounted,ref } from "vue";
import {useRouter} from "vue-router";
import {getCart,updateCartItem,removeCartItem,createProposalFromCart} from "../services/api.js";
import {readCartState,saveCartState,clearCartState} from "../composables/useCartState.js";
const router=useRouter(),items=ref([]),stokvel=ref(null),loading=ref(true),error=ref(""),busyItemId=ref(null),submitting=ref(false),showProposal=ref(false),proposalTitle=ref(""),proposalDescription=ref(""),deliveryAddress=ref("");
const total=computed(()=>items.value.reduce((s,i)=>s+Number(i.subtotal||0),0)),itemCount=computed(()=>items.value.reduce((s,i)=>s+Number(i.quantity||0),0));
function sync(){saveCartState({items:items.value,order:null,stokvel:stokvel.value})}
async function load(){loading.value=true;error.value="";const saved=readCartState();if(saved?.items?.length){items.value=saved.items;stokvel.value=saved.stokvel||null}try{const c=await getCart();items.value=c.items||[];stokvel.value=c.stokvel||stokvel.value;sync()}catch(e){if(saved?.items?.length){items.value=saved.items;stokvel.value=saved.stokvel||null}else error.value=e.response?.data?.message||"Unable to load your group basket."}finally{loading.value=false}}
async function change(item,n){const q=Number(item.quantity)+n;if(q<=0)return remove(item);await setQty(item,q)}async function setQty(item,q){busyItemId.value=item.order_item_id;try{const r=await updateCartItem(item.order_item_id,q);Object.assign(item,r.item);sync()}catch(e){error.value=e.response?.data?.message||"Unable to update that item."}finally{busyItemId.value=null}}async function remove(item){busyItemId.value=item.order_item_id;try{await removeCartItem(item.order_item_id);items.value=items.value.filter(x=>x.order_item_id!==item.order_item_id);items.value.length?sync():clearCartState()}catch(e){error.value=e.response?.data?.message||"Unable to remove that item."}finally{busyItemId.value=null}}
function openProposal(){error.value="";if(!items.value.length)return;proposalTitle.value=`${stokvel.value?.stokvel_name||'Group'} purchase proposal`;proposalDescription.value="Proposed group purchase for members to review and vote on.";showProposal.value=true}
async function submitProposal(){if(submitting.value||!deliveryAddress.value.trim())return;submitting.value=true;error.value="";try{await createProposalFromCart({title:proposalTitle.value,description:proposalDescription.value,delivery_address:deliveryAddress.value.trim()});clearCartState();showProposal.value=false;router.push("/proposals")}catch(e){error.value=e.response?.data?.message||"The purchase proposal could not be created."}finally{submitting.value=false}}
function money(v){return`R ${Number(v||0).toFixed(2)}`}function shop(){router.push("/catalogue")}onMounted(load)
</script>
<template><main class="cart-page"><section class="cart-container"><div class="cart-heading"><div><p class="eyebrow">GROUP PURCHASE PROPOSAL</p><h1>Prepare a group purchase</h1><p class="intro" v-if="stokvel">Shopping together with <strong>{{stokvel.stokvel_name}}</strong>. This basket becomes a proposal for the group to vote on.</p></div><button class="secondary-button continue-shopping" type="button" @click="shop"><span aria-hidden="true">←</span> Continue shopping</button></div><div v-if="error" class="message error-message">{{error}}</div><div v-if="loading" class="state-card">Loading your group basket…</div><div v-else-if="!items.length" class="empty-card"><div class="empty-icon">🛒</div><h2>Your basket is empty</h2><p>Add products from the catalogue to prepare a group purchase proposal.</p><button class="primary-button" @click="shop">Browse catalogue</button></div><div v-else class="cart-layout"><section class="items-card"><div class="card-header"><h2>Proposed items</h2><p>{{itemCount}} item{{itemCount===1?'':'s'}} in the proposal</p></div><article v-for="item in items" :key="item.order_item_id" class="cart-item"><div class="product-image-wrap"><img v-if="item.image_url" :src="item.image_url" :alt="item.product_name"/><span v-else>🛒</span></div><div class="item-details"><h3>{{item.product_name}}</h3><p>{{item.supplier_name}}</p><strong>{{money(item.unit_price)}} each</strong></div><div class="quantity-control"><button :disabled="busyItemId===item.order_item_id" @click="change(item,-1)">−</button><span>{{item.quantity}}</span><button :disabled="busyItemId===item.order_item_id" @click="change(item,1)">+</button></div><strong class="item-total">{{money(item.subtotal)}}</strong><button class="remove-button" :disabled="busyItemId===item.order_item_id" @click="remove(item)">Remove</button></article></section><aside class="summary-card"><p class="eyebrow">GROUP DECISION</p><h2>Submit for a vote</h2><div class="summary-line"><span>Items</span><strong>{{itemCount}}</strong></div><div class="summary-line"><span>Proposal total</span><strong>{{money(total)}}</strong></div><p class="summary-note">Submitting does not spend the wallet. Members vote first; an authorised Stokvel officer approves and authorises the purchase before money leaves the group wallet.</p><button class="primary-button confirm-button" :disabled="!items.length" @click="openProposal">Create purchase proposal</button></aside></div></section><div v-if="showProposal" class="modal-backdrop" @click.self="showProposal=false"><section class="confirm-modal" role="dialog" aria-modal="true" aria-labelledby="proposal-modal-title"><div class="modal-header"><div><p class="eyebrow">PURCHASE PROPOSAL</p><h2 id="proposal-modal-title">Send this purchase to the group.</h2><p class="modal-subtitle">Add the details members will use when deciding whether to approve this purchase.</p></div><button class="close" type="button" aria-label="Close purchase proposal" @click="showProposal=false">×</button></div><div class="modal-form"><div class="field-group"><label class="address-label" for="proposal-title">TITLE</label><input id="proposal-title" v-model="proposalTitle" class="address-input" autocomplete="off"/></div><div class="field-group"><label class="address-label" for="proposal-description">DESCRIPTION</label><textarea id="proposal-description" v-model="proposalDescription" class="address-input" rows="4"></textarea></div><div class="field-group"><label class="address-label" for="proposal-address">DELIVERY ADDRESS</label><input id="proposal-address" v-model="deliveryAddress" class="address-input" placeholder="Enter the proposed group delivery address" autocomplete="street-address"/></div></div><div class="confirm-stats"><div><span>ITEMS</span><strong>{{itemCount}}</strong></div><div><span>TOTAL</span><strong>{{money(total)}}</strong></div></div><div class="modal-actions"><button class="secondary-button" type="button" @click="showProposal=false">Cancel</button><button class="primary-button" type="button" :disabled="submitting||!deliveryAddress.trim()" @click="submitProposal">{{submitting?'Submitting…':'Submit for voting'}}</button></div></section></div></main></template>
<style scoped>
.cart-page{min-height:100vh;padding:36px 24px 60px;background:var(--sw-page-background);color:var(--sw-page-text)}.cart-container{max-width:1180px;margin:auto}.cart-heading{display:flex;justify-content:space-between;align-items:center;gap:24px;margin-bottom:28px}.eyebrow{font-size:11px;font-weight:800;letter-spacing:.14em;color:var(--sw-purple-700)}h1{font-size:42px;margin:0}h2,h3{color:var(--sw-page-text)}.intro,p{color:var(--sw-page-text-muted);line-height:1.6}.secondary-button,.primary-button,.remove-button{padding:13px 20px;border-radius:999px;font-weight:800;cursor:pointer}.secondary-button{border:1px solid var(--sw-input-border);background:var(--sw-page-surface);color:var(--sw-page-text)}.continue-shopping{display:inline-flex;align-items:center;justify-content:center;gap:9px;min-height:46px;padding:12px 18px;border-color:var(--sw-purple-700);color:var(--sw-purple-700);white-space:nowrap}.continue-shopping span{font-size:18px;line-height:1}.primary-button{border:0;background:var(--sw-purple-700);color:#fff}.primary-button:disabled,.secondary-button:disabled{opacity:.55;cursor:not-allowed}.message,.state-card,.empty-card,.items-card,.summary-card{border:1px solid var(--sw-input-border);border-radius:22px;background:var(--sw-page-surface);box-shadow:var(--sw-card-shadow)}.message{padding:14px;margin-bottom:18px;color:#b42318}.state-card,.empty-card{padding:50px;text-align:center}.cart-layout{display:grid;grid-template-columns:minmax(0,1fr) 330px;gap:22px}.items-card{overflow:hidden}.card-header{padding:24px;border-bottom:1px solid var(--sw-input-border)}.card-header h2{margin:0}.card-header p{margin:5px 0 0}.cart-item{display:grid;grid-template-columns:70px 1fr auto auto auto;align-items:center;gap:16px;padding:18px 22px;border-bottom:1px solid var(--sw-input-border)}.product-image-wrap{width:70px;height:70px;border-radius:12px;background:var(--sw-page-background);display:grid;place-items:center;overflow:hidden}.product-image-wrap img{width:100%;height:100%;objec