sw-page-text-soft)}.address-input{width:100%;box-sizing:border-box;padding:13px 14px;border-radius:13px;border:1px solid var(--sw-input-border);background:var(--sw-page-background);color:var(--sw-page-text);font:500 13px/1.45 inherit;outline:none;transition:border-color .18s ease,box-shadow .18s ease,background .18s ease}.address-input::placeholder{color:var(--sw-page-text-muted)}.address-input:focus{border-color:var(--sw-purple-700);box-shadow:0 0 0 3px rgba(121,93,137,.14);background:var(--sw-page-surface)}textarea.address-input{min-height:110px;resize:vertical}.confirm-stats{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:22px 0 4px}.confirm-stats div{padding:15px 16px;border-radius:14px;background:var(--sw-page-background);border:1px solid var(--sw-input-border)}.confirm-stats span{display:block;color:var(--sw-page-text-soft);font-size:9px;font-weight:800;letter-spacing:.12em}.confirm-stats strong{display:block;color:var(--sw-page-text);margin-top:5px;font-size:20px}.modal-actions{display:flex;justify-content:flex-end;gap:10px;margin-top:20px;padding-top:18px;border-top:1px solid var(--sw-input-border)}.modal-actions .secondary-button,.modal-actions .primary-button{min-height:46px}.modal-actions .primary-button{min-width:170px}@media(max-width:900px){.cart-layout{grid-template-columns:1fr}.summary-card{position:static}}@media(max-width:700px){.cart-heading{flex-direction:column;align-items:stretch}.continue-shopping{align-self:flex-start}.cart-item{grid-template-columns:56px 1fr}.quantity-control,.item-total,.remove-button{grid-column:2;justify-self:start}.modal-backdrop{padding:12px}.confirm-modal{padding:22px;border-radius:20px;max-height:calc(100vh - 24px)}.modal-header h2{font-size:27px}.confirm-stats{grid-template-columns:1fr}.modal-actions{flex-direction:column}.modal-actions>*{width:100%}.modal-actions .primary-button{min-width:0}}
